#include <stdio.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/err.h>
int main(void){char text[2048];unsigned char key[32],iv[16],cipher[4096],plain[4096];for(int i=0;i<32;i++)key[i]=(unsigned char)(i+1);for(int i=0;i<16;i++)iv[i]=(unsigned char)(0xA0+i);printf("AES-256-CBC demo (CBC mode with PKCS padding). Enter plaintext: ");if(!fgets(text,sizeof text,stdin))return 1;text[strcspn(text,"\r\n")]=0;EVP_CIPHER_CTX *ctx=EVP_CIPHER_CTX_new();if(!ctx)return 1;int n=0,total=0;if(EVP_EncryptInit_ex(ctx,EVP_aes_256_cbc(),NULL,key,iv)!=1||EVP_EncryptUpdate(ctx,cipher,&n,(unsigned char*)text,(int)strlen(text))!=1){puts("Encryption failed.");EVP_CIPHER_CTX_free(ctx);return 1;}total=n;if(EVP_EncryptFinal_ex(ctx,cipher+total,&n)!=1){puts("Encryption final failed.");EVP_CIPHER_CTX_free(ctx);return 1;}total+=n;EVP_CIPHER_CTX_free(ctx);printf("Ciphertext hex: ");for(int i=0;i<total;i++)printf("%02X",cipher[i]);puts("");ctx=EVP_CIPHER_CTX_new();int ptotal=0;if(EVP_DecryptInit_ex(ctx,EVP_aes_256_cbc(),NULL,key,iv)!=1||EVP_DecryptUpdate(ctx,plain,&n,cipher,total)!=1){puts("Decryption failed.");EVP_CIPHER_CTX_free(ctx);return 1;}ptotal=n;if(EVP_DecryptFinal_ex(ctx,plain+ptotal,&n)!=1){puts("Decryption final failed.");EVP_CIPHER_CTX_free(ctx);return 1;}ptotal+=n;plain[ptotal]=0;printf("Recovered plaintext: %s\n",plain);EVP_CIPHER_CTX_free(ctx);puts("Assignment note: AES-256-CBC is used as a modern stronger-than-DES example. For security, use authenticated encryption (e.g. AES-GCM) in real applications; this fixed demo key/IV is not production-safe.");return 0;}
